// Bierze listę zmienionych plików z payloadu GitHub Trigger
// i przepuszcza dalej tylko te, które faktycznie definiują endpointy API
const commits = $input.first().json.commits || [];
const wzorzec = /routes\/|controllers\/|api\//i;

const zmienionePliki = new Set();
for (const commit of commits) {
  (commit.added || []).forEach(f => zmienionePliki.add(f));
  (commit.modified || []).forEach(f => zmienionePliki.add(f));
}

const istotne = [...zmienionePliki].filter(f => wzorzec.test(f));

if (istotne.length === 0) {
  // Nic istotnego się nie zmieniło — zatrzymaj workflow, nie generuj dokumentacji na próżno
  return [];
}

return istotne.map(plik => ({ json: { plik } }));

// Prosta walidacja: czy AI faktycznie zwróciło markdown z nagłówkami,
// a nie np. przeprosiny albo pustą odpowiedź.
const tresc = $json.message?.content || $json.text || '';

if (!tresc.includes('#') || tresc.length < 50) {
  throw new Error('Wygenerowana dokumentacja wygląda podejrzanie krótko/niepoprawnie — zatrzymuję workflow zamiast commitować śmieci.');
}

return [{ json: { dokumentacja: tresc, plikZrodlowy: $('Filtruj: tylko pliki tras/kontrolerów').item.json.plik } }];
